CREATE TABLE IF NOT EXISTS depth_updates (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, first_update_id UBIGINT, final_update_id UBIGINT, source VARCHAR, bids JSON, asks JSON);
ALTER TABLE depth_updates ADD COLUMN IF NOT EXISTS bids JSON;
ALTER TABLE depth_updates ADD COLUMN IF NOT EXISTS asks JSON;
CREATE TABLE IF NOT EXISTS depth_levels (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, first_update_id UBIGINT, final_update_id UBIGINT, side VARCHAR, level INTEGER, price DECIMAL(38,18), quantity DECIMAL(38,18), source VARCHAR);
